async function makeAvatarDataUrl(file){const bitmap=await new Promise((resolve,reject)=>{const fallback=()=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{URL.revokeObjectURL(url);resolve(image)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Image decoding failed'))};image.src=url};if(typeof window.createImageBitmap==='function')window.createImageBitmap(file).then(resolve,fallback);else fallback()});try{const maxSide=256,scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)throw new Error('Canvas unavailable');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);for(const q of [.78,.62,.48,.34]){const data=canvas.toDataURL('image/jpeg',q);if(data.length<=180000)return data}throw new Error('الصورة المضغوطة ما زالت كبيرة لقاعدة البيانات')}finally{bitmap.close?.()}}
