function normalizePosts(raw){remoteRawPosts=raw||{};cloudPosts=Object.entries(remoteRawPosts).filter(([,v])=>v?.data).map(([id,v])=>{const d=v.data,reactions=v.reactions||{},comments=Object.entries(v.comments||{}).map(([commentId,c])=>({...c,id:commentId})).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0));const likedBy=Object.keys(reactions).filter(uid=>reactions[uid]===true);return {...d,tags:Array.isArray(d.tags)?d.tags:Object.values(d.tags||{}),id,comments,likedBy,likes:likedBy.length}}).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));cloudReady=true;if(!['compose','messages','settings'].includes(page))renderPage()}
