function syncGroupWatchers(){groupRequestUnsubs.forEach(fn=>fn());groupRequestUnsubs=[];if(!activeUser)return;for(const g of remoteGroups){const path=g.ownerUid===activeUser.uid?`groupRequests/${g.id}`:(g.visibility==='private'&&!isGroupMember(g)?`groupRequests/${g.id}/${activeUser.uid}`:'');if(!path)continue;const r=database.ref(path),fn=s=>{if(g.ownerUid===activeUser.uid)groupRequestData[g.id]=s.val()||{};else groupPendingStatus[g.id]=!!s.val();if(page==='groups')renderPage()};r.on('value',fn,reportFirebaseError);groupRequestUnsubs.push(()=>r.off('value',fn))}}
function replaceGroups(raw){rawGroupData=raw||{};remoteGroups=Object.entries(rawGroupData).map(([id,g])=>({...g,id,visibility:g.visibility==='private'?'private':'public'})).filter(g=>typeof g.ownerUid==='string'&&g.ownerUid.length>0&&typeof g.name==='string'&&g.name.trim().length>=2);groups.splice(0,groups.length,...remoteGroups);syncMembershipWatchers();syncGroupWatchers();if(page==='groups'||page==='home'||page==='group-detail')renderFrame()}
