async function updateProfile(patch){if(!activeUser?.uid)throw new Error('سجّل الدخول أولاً.');const ref=database.ref(`profiles/${activeUser.uid}`),snap=await ref.once('value'),current=snap.val()||await ensureProfile(auth.currentUser);const next={...current,...patch,uid:activeUser.uid,joinedAt:Number(current.joinedAt)||Date.now()};await ref.set(next);activeUser={...activeUser,...next};if(auth.currentUser)publicProfiles[activeUser.uid]=next;renderFrame();return next}
