async function signInGoogle(){if(!auth){toast('خدمات تسجيل الدخول غير متاحة بعد؛ انتظر لحظات ثم أعد المحاولة.');return}const provider=new firebase.auth.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});try{if(/\.github\.io$/i.test(location.hostname)){await auth.signInWithRedirect(provider);return}await auth.signInWithPopup(provider);page='home';closeModal();toast('تم تسجيل الدخول باستخدام Google')}catch(e){reportFirebaseError(e)}}
