function initFirebaseData(){if((!auth||!database)&&typeof firebase!=='undefined'&&firebase.apps){firebaseAvailable=true;firebaseApp=firebase.apps.length?firebase.app():firebase.initializeApp(firebaseConfig);activateAppCheck();auth=firebase.auth(firebaseApp);database=firebase.database(firebaseApp);if(auth)auth.useDeviceLanguage();try{if(location.protocol!=='file:'&&firebase.analytics)firebase.analytics(firebaseApp)}catch{}}const w=document.querySelector('#sdkWarning');if(!auth||!database){renderVisitor();if(w){w.hidden=false;w.textContent='جارٍ الاتصال بخدمات Firebase؛ ستظل واجهة الموقع مستجيبة.'}return false}if(w)w.hidden=true;if(!firebaseAuthStarted){firebaseAuthStarted=true;authState();auth.getRedirectResult().catch(reportFirebaseError)}return true}
