async function addComment(postId,text){if(!activeUser)throw new Error('سجّل الدخول لإضافة تعليق.');const p=findPost(postId);if(!p)throw new Error('المنشور غير متاح في Firebase بعد.');const r=database.ref(`${postRootPath(p)}/comments`).push();await r.set({uid:activeUser.uid,name:activeUser.name,text,createdAt:Date.now()});if(p.uid!==activeUser.uid){try{await addNotification(p.uid,{postId,commentId:r.key,type:'comment',...(p.privateGroupId?{groupId:p.privateGroupId}:{}),text:`علّق ${activeUser.name} على منشورك.`})}catch(notificationError){console.warn('Codna: التعليق حُفظ، لكن تعذّر إرسال إشعار التعليق.',notificationError)}}}
function notifyWrite(fn){Promise.resolve(fn()).catch(reportFirebaseError)}
