const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,f){try{const v=JSON.parse(localStorage.getItem(k));return v===null?f:v}catch{return f}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('تعذر الحفظ في المتصفح؛ قد تكون مساحة التخزين ممتلئة.')}}
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const timeAgo=ts=>{const m=Math.max(1,Math.floor((Date.now()-ts)/60000));if(language==='en'){if(m<60)return `${m}m ago`;const h=Math.floor(m/60);if(h<24)return `${h}h ago`;return `${Math.floor(h/24)}d ago`}if(m<60)return `منذ ${m} د`;const h=Math.floor(m/60);if(h<24)return `منذ ${h} س`;return `منذ ${Math.floor(h/24)} ي`};
