function setTheme(mode,persist=true){const theme=mode==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=theme==='dark'?'#0e1521':'#f4f7fb';const button=document.querySelector('#themeToggle');if(button){button.innerHTML=theme==='dark'?'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/></svg>':'<svg viewBox="0 0 24 24"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5 8.6 8.6 0 1 0 20.5 14.2Z"/></svg>';button.setAttribute('aria-label',localizeText(theme==='dark'?'تفعيل الوضع الفاتح':'تفعيل الوضع الليلي'));button.title=button.getAttribute('aria-label')}if(persist)write('codna_html_theme_v1',theme);const setting=document.querySelector('#themeSettingButton');if(setting)setting.textContent=localizeText(theme==='dark'?'التبديل إلى الوضع الفاتح':'التبديل إلى الوضع الليلي')}
